for a in range(64):
    for b in range(64):
        for lo in range(6):
            for hi in range(lo, 6):
                width = hi - lo + 1
                mask = (1 << width) - 1
                x, y = (a >> lo) & mask, (b >> lo) & mask
                G, P = group_gp(a, b, lo, hi)
                assert G in (0, 1) and P in (0, 1)
                for cin in (0, 1):
                    carry_out = (x + y + cin) >> width
                    assert carry_out == (G | (P & cin)), f"a={a:06b} b={b:06b} bits {lo}..{hi} cin={cin}"
                assert P == int((x ^ y) == mask), f"P should be 1 exactly when every position propagates (a={a:06b}, b={b:06b}, bits {lo}..{hi})"
print("All tests passed!")
